package graph

// External-service seams for the resolvers. Stripe and Mailgun used to be
// constructed inline from env vars inside each resolver, which made the
// success paths (payment confirmed -> order saved, stock decremented, emails
// sent) impossible to exercise in tests. Resolver.Payments / Resolver.Mailer
// let tests inject fakes; when left nil (as in internal/server/routes.go) the
// real clients below are used, built per call from the same env vars as
// before, so production behavior is unchanged.
//
// This file is NOT regenerated by gqlgen.

import (
	"context"
	"os"

	"github.com/stripe/stripe-go/v84"

	"storeapi/internal/emails"
)

// PaymentGateway is the slice of Stripe's PaymentIntents API the resolvers use.
type PaymentGateway interface {
	RetrieveIntent(ctx context.Context, id string) (*stripe.PaymentIntent, error)
	UpdateIntent(ctx context.Context, id string, params *stripe.PaymentIntentUpdateParams) (*stripe.PaymentIntent, error)
	CreateIntent(ctx context.Context, params *stripe.PaymentIntentCreateParams) (*stripe.PaymentIntent, error)
}

// Mailer sends a rendered template to a recipient ("" = ADMIN_EMAIL) and
// returns the provider's message id. It has emails.Send's signature.
type Mailer interface {
	Send(template string, variables emails.Variables, recipient string) (string, error)
}

type stripeGateway struct{}

func (stripeGateway) client() *stripe.Client {
	return stripe.NewClient(os.Getenv("STRIPE_SECRET_KEY"))
}

func (g stripeGateway) RetrieveIntent(ctx context.Context, id string) (*stripe.PaymentIntent, error) {
	return g.client().V1PaymentIntents.Retrieve(ctx, id, nil)
}

func (g stripeGateway) UpdateIntent(ctx context.Context, id string, params *stripe.PaymentIntentUpdateParams) (*stripe.PaymentIntent, error) {
	return g.client().V1PaymentIntents.Update(ctx, id, params)
}

func (g stripeGateway) CreateIntent(ctx context.Context, params *stripe.PaymentIntentCreateParams) (*stripe.PaymentIntent, error) {
	return g.client().V1PaymentIntents.Create(ctx, params)
}

type mailgunMailer struct{}

func (mailgunMailer) Send(template string, variables emails.Variables, recipient string) (string, error) {
	return emails.Send(template, variables, recipient)
}

func (r *Resolver) payments() PaymentGateway {
	if r.Payments != nil {
		return r.Payments
	}
	return stripeGateway{}
}

func (r *Resolver) mailer() Mailer {
	if r.Mailer != nil {
		return r.Mailer
	}
	return mailgunMailer{}
}
